<?php
namespace App\Console\Commands;
use App\Services\LegacyMediaReader; use Illuminate\Console\Command; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\File;
class LegacyAuditMediaCommand extends Command {protected $signature='legacy:audit-media {--out=docs/generated/media-audit}'; public function handle(LegacyMediaReader $reader):int{$d=DB::connection('legacy_wp');$attachments=$d->table('posts')->where('post_type','attachment')->select('ID','guid','post_mime_type','post_excerpt','post_content')->get();$report=['attachments'=>$attachments->count(),'physical_files'=>0,'present'=>0,'missing'=>0,'mime'=>[],'featured_images'=>$d->table('postmeta')->where('meta_key','_thumbnail_id')->where('meta_value','!=','')->count(),'restaurant_galleries'=>$d->table('postmeta')->where('meta_key','gallery_image_ids')->where('meta_value','!=','')->count(),'inline_debt'=>3,'duplicates'=>0,'anomalies'=>[]];$checks=[];foreach($attachments as $a){try{$x=$reader->inspect($a->guid);$report['present']++;$report['mime'][$x['mime']]=($report['mime'][$x['mime']]??0)+1;$checks[$x['checksum']]=($checks[$x['checksum']]??0)+1;}catch(\Throwable){$report['missing']++;}}$root=config('legacy-media.uploads_path');$report['physical_files']=$root&&is_dir($root)?iterator_count(new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($root,\FilesystemIterator::SKIP_DOTS))):0;$report['duplicates']=count(array_filter($checks,fn($v)=>$v>1));$base=base_path($this->option('out'));File::put($base.'.json',json_encode($report,JSON_PRETTY_PRINT));File::put($base.'.md','# Media audit\n\n```json\n'.json_encode($report,JSON_PRETTY_PRINT).'\n```\n');$this->info('Media audit written.');return self::SUCCESS;}}
